export const PROJECTS_STORAGE_KEY = "ferryx.projects";
export const ACTIVE_PROJECT_STORAGE_KEY = "ferryx.active-project";
export const SIDEBAR_OPEN_STORAGE_KEY = "ferryx.sidebar.open";
export const SIDEBAR_WIDTH_STORAGE_KEY = "ferryx.sidebar.width";
export const SIDEBAR_COLLAPSED_PROJECTS_STORAGE_KEY = "ferryx.sidebar.collapsedProjects";
export const TERMINAL_SETTINGS_STORAGE_KEY = "ferryx.terminal.settings";
export const NOTIFICATION_SETTINGS_STORAGE_KEY = "ferryx.settings.notifications:v1";
export const APPEARANCE_SETTINGS_STORAGE_KEY = "ferryx.settings.appearance";
export const QUICK_COMMANDS_STORAGE_KEY = "ferryx.settings.quickCommands";
export const BROWSER_SETTINGS_STORAGE_KEY = "ferryx.settings.browser";

export const LEGACY_STORAGE_KEY_MAP: Record<string, string[]> = {
  [PROJECTS_STORAGE_KEY]: ["rorca.projects", "orca.projects"],
  [ACTIVE_PROJECT_STORAGE_KEY]: ["rorca.active-project", "orca.active-project"],
  [SIDEBAR_OPEN_STORAGE_KEY]: ["orca.sidebar.open", "rorca.sidebar.open"],
  [SIDEBAR_WIDTH_STORAGE_KEY]: ["orca.sidebar.width", "rorca.sidebar.width"],
  [SIDEBAR_COLLAPSED_PROJECTS_STORAGE_KEY]: ["rorca.sidebar.collapsedProjects", "orca.sidebar.collapsedProjects"],
  [TERMINAL_SETTINGS_STORAGE_KEY]: ["orca.terminal.settings", "rorca.terminal.settings"],
  [NOTIFICATION_SETTINGS_STORAGE_KEY]: ["rorca:settings:notifications:v1", "orca:settings:notifications:v1"],
};

export function getMigratedItem(
  key: string,
  storage: Pick<Storage, "getItem" | "setItem"> | null = typeof window !== "undefined" && window.localStorage ? window.localStorage : null,
): string | null {
  if (!storage) return null;
  const value = storage.getItem(key);
  if (value !== null) return value;

  const legacyKeys = LEGACY_STORAGE_KEY_MAP[key] ?? [];
  for (const legacyKey of legacyKeys) {
    const legacyVal = storage.getItem(legacyKey);
    if (legacyVal !== null) {
      try {
        storage.setItem(key, legacyVal);
      } catch {
        // ignore quota or disabled storage error
      }
      return legacyVal;
    }
  }
  return null;
}

import { normalizeLayout } from "../state/layout";
import { collectLeafIds, createLeafNode } from "../state/paneTree";
import type { WorkspaceState } from "../state/workspaceStore";
import {
  worktreeIdentity,
  type BrowserTab,
  type LayoutState,
  type PersistedLayout,
  type PersistedTab,
  type PersistedTerminalSession,
  type PersistedWorkspace,
  type PersistedWorkspaceSession,
  type PersistedWorktree,
  type TabGroup,
  type TerminalSession,
  type TerminalTab,
  type WorkspaceTab,
  type Worktree,
} from "./types";

export const WORKSPACE_SESSION_VERSION = 2;

export function serializeWorkspaceState(
  workspaceId: string,
  repoRoot: string,
  state: WorkspaceState,
): PersistedWorkspaceSession {
  const normalizedLayout = normalizeLayout(state.layout);
  const persistedWorktrees: PersistedWorktree[] = state.worktrees.map((wt) => ({
    path: wt.path,
    branch: wt.branch ?? "",
    head: wt.head,
    isMain: !wt.branch || wt.branch === "main" || wt.branch === "master",
    isLocked: Boolean(wt.locked),
  }));

  const persistedTabs: PersistedTab[] = normalizedLayout.tabs.map((tab) => {
    if (tab.kind === "browser") {
      return {
        id: tab.id,
        kind: "browser",
        label: tab.label,
        pinned: Boolean(tab.pinned),
        browser: {
          browserId: tab.browserId,
          url: tab.url,
          title: tab.title ?? null,
          loading: tab.loading,
          canGoBack: tab.canGoBack,
          canGoForward: tab.canGoForward,
        },
      };
    }

    const tabLayout = normalizedLayout.layoutsByTabId[tab.id];
    return {
      id: tab.id,
      kind: "terminal",
      label: tab.label,
      pinned: Boolean(tab.pinned),
      terminal: tabLayout
        ? {
            primarySessionId: tab.sessionId,
            paneTree: tabLayout.root,
            sessionIdsByLeafId: { ...tabLayout.sessionIdsByLeafId },
            activeLeafId: tabLayout.activeLeafId,
            expandedLeafId: tabLayout.expandedLeafId,
          }
        : {
            primarySessionId: tab.sessionId,
            paneTree: createLeafNode(`leaf-persisted:${tab.id}`),
            sessionIdsByLeafId: { [`leaf-persisted:${tab.id}`]: tab.sessionId },
            activeLeafId: `leaf-persisted:${tab.id}`,
            expandedLeafId: null,
          },
    };
  });

  const persistedLayout: PersistedLayout = {
    splitMode: normalizedLayout.split ?? "none",
    primaryTabId: normalizedLayout.primaryTabId ?? null,
    secondaryTabId: normalizedLayout.secondaryTabId ?? null,
    activeTabId: normalizedLayout.activeTabId ?? null,
    tabs: persistedTabs,
    tabGroups: Object.values(normalizedLayout.tabGroups ?? {}).map((group) => ({
      id: group.id,
      tabIds: [...group.tabIds],
      activeTabId: group.activeTabId,
    })),
    tabGroupLayout: normalizedLayout.tabGroupLayout ?? null,
    focusedGroupId: normalizedLayout.focusedGroupId ?? null,
  };

  const persistedTerminalSessions: Record<string, PersistedTerminalSession> = {};
  const createdAt = Date.now();
  const referencedSessionIds = new Set<string>();
  for (const tab of persistedTabs) {
    if (tab.kind === "browser") continue;
    const terminal = tab.terminal;
    if (terminal?.primarySessionId) referencedSessionIds.add(terminal.primarySessionId);
    for (const sessionId of Object.values(terminal?.sessionIdsByLeafId ?? {})) {
      if (sessionId) referencedSessionIds.add(sessionId);
    }
  }
  for (const [id, sess] of Object.entries(state.sessions)) {
    if (!sess || !referencedSessionIds.has(id)) continue;
    persistedTerminalSessions[id] = {
      localSessionId: sess.id,
      backendSessionId: sess.backendSessionId,
      worktreePath: sess.worktreePath ?? sess.cwd,
      cwd: sess.cwd,
      createdAt,
    };
  }

  const workspace: PersistedWorkspace = {
    workspaceId,
    repoRoot,
    worktrees: persistedWorktrees,
    activeWorktreePath: state.activeWorktreePath,
    layout: persistedLayout,
    terminalSessions: persistedTerminalSessions,
  };

  return {
    version: WORKSPACE_SESSION_VERSION,
    timestamp: Date.now(),
    activeWorkspaceId: workspaceId,
    workspaces: {
      [workspaceId]: workspace,
    },
  };
}

export function deserializeWorkspaceState(
  workspaceId: string,
  persistedSession: PersistedWorkspaceSession,
  liveBackendSessionIds?: Iterable<string> | null,
): WorkspaceState | null {
  const ws = persistedSession.workspaces?.[workspaceId];
  if (!ws) return null;
  const isV2 = (persistedSession.version ?? 1) >= 2;

  const liveSet = liveBackendSessionIds
    ? (liveBackendSessionIds instanceof Set ? liveBackendSessionIds : new Set(liveBackendSessionIds))
    : null;

  const worktrees: Worktree[] = (ws.worktrees || []).map((wt) => ({
    path: wt.path,
    branch: wt.branch ? (wt.branch.startsWith("refs/heads/") ? wt.branch : `refs/heads/${wt.branch}`) : null,
    head: wt.head,
    bare: false,
    detached: false,
    locked: wt.isLocked ? "locked" : null,
    prunable: null,
  }));

  const sessions: Record<string, TerminalSession> = {};
  for (const [mapKey, sess] of Object.entries(ws.terminalSessions || {})) {
    const localSessionId = sess.localSessionId || mapKey || sess.sessionId || "";
    if (!localSessionId) continue;
    const persistedBackendSessionId = isV2 ? (sess.backendSessionId ?? null) : (sess.backendSessionId ?? sess.sessionId ?? null);
    const backendSessionId = liveSet
      ? (persistedBackendSessionId && liveSet.has(persistedBackendSessionId) ? persistedBackendSessionId : null)
      : persistedBackendSessionId;
    const worktreePath = sess.worktreePath || sess.cwd;
    const matchingWorktree = worktrees.find((wt) => wt.path === worktreePath);
    sessions[localSessionId] = {
      id: localSessionId,
      cwd: sess.cwd || worktreePath,
      worktreePath,
      workspaceId,
      worktree: matchingWorktree ? worktreeIdentity(matchingWorktree) : null,
      backendSessionId,
      lifecycle: backendSessionId ? "working" : "exited",
    };
  }

  const tabs: WorkspaceTab[] = (ws.layout?.tabs || []).map((persistedTab): WorkspaceTab => {
    if (persistedTab.kind === "browser" || persistedTab.browser) {
      const browser = persistedTab.browser;
      const tab: BrowserTab = {
        id: persistedTab.id,
        kind: "browser",
        label: persistedTab.label,
        browserId: browser?.browserId ?? persistedTab.sessionId ?? `restored-browser:${persistedTab.id}`,
        url: browser?.url ?? "about:blank",
        title: browser?.title ?? persistedTab.label,
        canGoBack: browser?.canGoBack ?? false,
        canGoForward: browser?.canGoForward ?? false,
        loading: browser?.loading ?? false,
        pinned: Boolean(persistedTab.pinned),
      };
      return tab;
    }

    const primarySessionId = persistedTab.terminal?.primarySessionId ?? persistedTab.sessionId ?? "";
    const tab: TerminalTab = {
      id: persistedTab.id,
      kind: "terminal",
      sessionId: primarySessionId,
      label: persistedTab.label,
      pinned: Boolean(persistedTab.pinned),
    };
    return tab;
  });

  const layoutsByTabId: LayoutState["layoutsByTabId"] = {};
  for (const persistedTab of ws.layout?.tabs || []) {
    if (persistedTab.kind === "browser" || persistedTab.browser) {
      const leafId = `leaf-browser:${persistedTab.id}`;
      layoutsByTabId[persistedTab.id] = {
        root: createLeafNode(leafId),
        activeLeafId: leafId,
        expandedLeafId: null,
        sessionIdsByLeafId: { [leafId]: "" },
      };
      continue;
    }

    const terminal = persistedTab.terminal;
    const legacyTabLayout = ws.layout?.layoutsByTabId?.[persistedTab.id];
    const paneTree = terminal?.paneTree ?? persistedTab.paneTree ?? legacyTabLayout?.root;
    const primarySessionId = terminal?.primarySessionId ?? persistedTab.sessionId ?? "";
    const root = paneTree ?? createLeafNode(`leaf-restored:${persistedTab.id}`);
    const leafIds = collectLeafIds(root);
    const persistedMapping =
      terminal?.sessionIdsByLeafId ?? persistedTab.sessionIdsByLeafId ?? legacyTabLayout?.sessionIdsByLeafId;
    const sessionIdsByLeafId = persistedMapping && Object.keys(persistedMapping).length > 0
      ? Object.fromEntries(leafIds.map((leafId) => [leafId, persistedMapping[leafId] ?? primarySessionId]))
      : Object.fromEntries(leafIds.map((leafId) => [leafId, primarySessionId]));
    const requestedActiveLeafId =
      terminal?.activeLeafId ?? persistedTab.activeLeafId ?? legacyTabLayout?.activeLeafId ?? null;
    const requestedExpandedLeafId =
      terminal?.expandedLeafId ?? persistedTab.expandedLeafId ?? legacyTabLayout?.expandedLeafId ?? null;
    layoutsByTabId[persistedTab.id] = {
      root,
      activeLeafId: requestedActiveLeafId && leafIds.includes(requestedActiveLeafId) ? requestedActiveLeafId : leafIds[0] ?? null,
      expandedLeafId:
        requestedExpandedLeafId && leafIds.includes(requestedExpandedLeafId) ? requestedExpandedLeafId : null,
      sessionIdsByLeafId,
    };
  }

  const tabGroups: Record<string, TabGroup> | undefined = ws.layout?.tabGroups?.length
    ? Object.fromEntries(
        ws.layout.tabGroups.map((group) => [
          group.id,
          { id: group.id, tabIds: [...group.tabIds], activeTabId: group.activeTabId },
        ]),
      )
    : undefined;

  const layout = normalizeLayout({
    tabs,
    primaryTabId: ws.layout?.primaryTabId || (tabs[0]?.id ?? null),
    secondaryTabId: ws.layout?.secondaryTabId || null,
    activeTabId: ws.layout?.activeTabId || (tabs[0]?.id ?? null),
    split: (ws.layout?.splitMode as LayoutState["split"]) || "none",
    nestedSplit: null,
    layoutsByTabId,
    tabGroups,
    tabGroupLayout: ws.layout?.tabGroupLayout ?? null,
    focusedGroupId: ws.layout?.focusedGroupId ?? null,
  });

  const referencedSessionIds = new Set<string>();
  for (const tab of layout.tabs) {
    if (tab.kind === "browser") continue;
    if (tab.sessionId) referencedSessionIds.add(tab.sessionId);
    const tabLayout = layout.layoutsByTabId[tab.id];
    for (const sessionId of Object.values(tabLayout?.sessionIdsByLeafId ?? {})) {
      if (sessionId) referencedSessionIds.add(sessionId);
    }
  }
  const referencedSessions = Object.fromEntries(
    Object.entries(sessions).filter(([sessionId]) => referencedSessionIds.has(sessionId)),
  );

  return {
    worktrees,
    activeWorktreePath: ws.activeWorktreePath || (worktrees[0]?.path ?? null),
    sessions: referencedSessions,
    layout,
    unreadTabIds: {},
    unreadWorktreePaths: {},
    activityBySessionId: {},
  };
}

import { PanelLeft } from "lucide-react";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";

import { CommandPalette } from "./components/CommandPalette";
import { AddProjectDialog, AddWorktreeDialog } from "./components/ProjectDialogs";
import { SettingsDialog } from "./components/SettingsDialog";
import { Sidebar } from "./components/Sidebar";
import { TerminalSplitView } from "./components/TerminalSplitView";
import { WorktreeDeleteDialog } from "./components/WorktreeDeleteDialog";
import { IconButton } from "./components/ui/IconButton";
import { deserializeWorkspaceState, serializeWorkspaceState } from "./lib/sessionPersistence";
import { isMacShortcutPlatform, useShortcuts } from "./lib/shortcuts";
import {
  AGENT_CANDIDATES,
  AGENTS_SETTINGS_CHANGED_EVENT,
  getLaunchableAgents,
  loadAgentSettings,
  mergeDetections,
  type AgentSettings,
} from "./lib/agentsSettings";
import {
  ACTIVE_PROJECT_STORAGE_KEY,
  getMigratedItem,
  PROJECTS_STORAGE_KEY,
  SIDEBAR_COLLAPSED_PROJECTS_STORAGE_KEY,
  SIDEBAR_OPEN_STORAGE_KEY,
} from "./lib/storageKeys";
import {
  DEFAULT_WORKSPACE_ID,
  detectAgents,
  getWorktreeStatus,
  isTauriRuntime,
  loadSession,
  onNewTerminalTabMenu,
  registerProject,
  saveSession,
  spawnTerminal,
  writeTerminal,
  type AgentDetection,
  type RegisteredProject,
} from "./lib/tauri";
import { ensureTerminalEvents } from "./lib/terminalEvents";
import { useTerminalSettings } from "./lib/terminalSettings";
import { defaultTauriTransport } from "./lib/terminalTransport/tauriTransport";
import { worktreeIdentity, type DirtyState, type WorkspaceTab, type Worktree } from "./lib/types";
import { registerWindowCloseGuard } from "./lib/updater";
import { collectLeafIds, type PaneDirection } from "./state/paneTree";
import { useWorkspaceRuntime } from "./state/workspaceRuntime";
import { useWorkspaceStore } from "./state/workspaceStore";

export { ACTIVE_PROJECT_STORAGE_KEY, PROJECTS_STORAGE_KEY, SIDEBAR_OPEN_STORAGE_KEY };
const DEFAULT_PROJECT: RegisteredProject = { workspaceId: DEFAULT_WORKSPACE_ID, repoRoot: "." };

export function App() {
  const [projects, setProjects] = useState<RegisteredProject[]>(loadProjects);
  const [activeProjectId, setActiveProjectId] = useState(loadActiveProjectId);
  const restoredProjectIdRef = useRef<string | null>(null);
  const activeProject = useMemo(
    () => projects.find((project) => project.workspaceId === activeProjectId) ?? projects[0] ?? DEFAULT_PROJECT,
    [activeProjectId, projects],
  );

  const [agentSettings, setAgentSettings] = useState<AgentSettings>(loadAgentSettings);
  const [agentDetections, setAgentDetections] = useState<AgentDetection[]>([]);

  useEffect(() => {
    let cancelled = false;
    async function runDetection() {
      if (!isTauriRuntime()) return;
      try {
        const results = await detectAgents([...AGENT_CANDIDATES]);
        if (!cancelled) setAgentDetections(results);
      } catch (error) {
        console.warn("Failed to detect agents:", error);
      }
    }
    void runDetection();
    return () => {
      cancelled = true;
    };
  }, []);

  useEffect(() => {
    const handleSettingsChange = () => {
      setAgentSettings(loadAgentSettings());
    };
    window.addEventListener(AGENTS_SETTINGS_CHANGED_EVENT, handleSettingsChange);
    return () => window.removeEventListener(AGENTS_SETTINGS_CHANGED_EVENT, handleSettingsChange);
  }, []);

  const resolvedAgents = useMemo(
    () => mergeDetections(agentSettings, agentDetections),
    [agentSettings, agentDetections],
  );

  const launchableAgents = useMemo(
    () => getLaunchableAgents(resolvedAgents),
    [resolvedAgents],
  );

  const {
    state,
    agents,
    tabActivity,
    worktreeActivity,
    updateSessionTitleActivity,
    openTab,
    createBrowserTab,
    navigateBrowserTab,
    reloadBrowserTab,
    ensureTabForWorktree,
    closeTab,
    closeOtherTabs,
    closeTabsToRight,
    closeTabsToLeft,
    splitPane,
    moveTabToGroup,
    moveTabToSplit,
    detachPaneToTab,
    closePane,
    activateTab,
    reorderTab,
    renameTab,
    setTabPinned,
    focusPane,
    setPaneRatio,
    setTabGroupRatio,
    swapPanes,
    syncWorktrees,
    restoreWorkspace,
  } = useWorkspaceStore({ workspaceId: activeProject.workspaceId });
  const { runtimeError, refreshWorktrees, reportRuntimeError } = useWorkspaceRuntime({
    workspaceId: activeProject.workspaceId,
    activeWorktreePath: state.activeWorktreePath,
    syncWorktrees,
    ensureTabForWorktree,
  });

  useEffect(() => {
    void registerProject({
      workspaceId: activeProject.workspaceId,
      repoPath: activeProject.repoRoot,
    })
      .then(() => refreshWorktrees())
      .catch(reportRuntimeError);
  }, [activeProject.repoRoot, activeProject.workspaceId, refreshWorktrees, reportRuntimeError]);

  // Initial session restore on startup & HMR recovery.
  useEffect(() => {
    if (restoredProjectIdRef.current === activeProject.workspaceId) return;
    restoredProjectIdRef.current = activeProject.workspaceId;
    let cancelled = false;
    async function restore() {
      try {
        const session = await loadSession();
        if (cancelled || !session) return;

        const liveSessions = await defaultTauriTransport.listSessions().catch(() => []);
        const liveBackendIds = new Set(liveSessions.map((candidate) => candidate.sessionId));
        const restoredState = deserializeWorkspaceState(activeProject.workspaceId, session, liveBackendIds);

        if (restoredState && restoredState.layout.tabs.length > 0) {
          restoreWorkspace(restoredState);

          // A persisted local session can outlive its native PTY. Respawn only the dead
          // native side while preserving the local session/leaf ownership graph.
          const deadSessions = Object.values(restoredState.sessions).filter((candidate) => !candidate.backendSessionId);
          if (deadSessions.length > 0) {
            let hasSpawned = false;
            await ensureTerminalEvents().catch(() => undefined);
            for (const restoredSession of deadSessions) {
              if (cancelled) return;
              try {
                const worktreePath = restoredSession.worktreePath ?? restoredSession.cwd;
                const foundWorktree = restoredState.worktrees.find((worktree) => worktree.path === worktreePath);
                const backendSessionId = await spawnTerminal({
                  workspaceId: activeProject.workspaceId,
                  worktree: foundWorktree ? worktreeIdentity(foundWorktree) : null,
                  cwd: restoredSession.cwd,
                });
                restoredSession.backendSessionId = backendSessionId;
                restoredSession.lifecycle = "working";
                hasSpawned = true;
              } catch (error) {
                console.warn("Failed to respawn terminal session on restore:", error);
              }
            }

            if (hasSpawned && !cancelled) restoreWorkspace({ ...restoredState });
          }
          // Typed v2 restoration already reconstructed every tab. Do not run the legacy
          // per-worktree fallback as well or it can create duplicate terminal tabs.
          return;
        }

        // Legacy best-effort fallback for sessions that cannot be deserialized as a
        // workspace state. Browser records are skipped because they require explicit v2
        // browser metadata and should never be guessed from terminal fields.
        const workspace = session.workspaces?.[activeProject.workspaceId];
        if (!workspace || !workspace.layout?.tabs?.length) return;

[621 more lines in file. Use offset=201 to continue.]

        for (const persistedTab of workspace.layout.tabs) {
          if (cancelled) return;
          if (persistedTab.kind === "browser") continue;
          const legacyWorktreePath = persistedTab.worktreePath || workspace.repoRoot;
          const found = workspace.worktrees?.find((candidate) => candidate.path === legacyWorktreePath);
          const worktree: Worktree = found
            ? {
                path: found.path,
                head: found.head,
                branch: found.branch,
                bare: false,
                detached: false,
                locked: found.isLocked ? "locked" : null,
                prunable: null,
              }
            : {
                path: legacyWorktreePath,
                head: "",
                branch: persistedTab.label,
                bare: false,
                detached: false,
                locked: null,
                prunable: null,
              };
          try {
            const alreadyOpen = state.layout.tabs.some((tab) => {
              if (tab.kind === "browser") return false;
              const localSession = state.sessions[tab.sessionId];
              return (localSession?.worktreePath ?? localSession?.cwd) === worktree.path;
            });
            if (!alreadyOpen) await ensureTabForWorktree(worktree);
          } catch {
            // Safe fallback if the terminal for this worktree is already open.
          }
        }
      } catch (error) {
        console.warn("Session restore on boot skipped:", error);
      }
    }
    void restore();
    return () => {
      cancelled = true;
    };
  }, [activeProject.workspaceId, ensureTabForWorktree, restoreWorkspace]);

  useEffect(() => {
    const unregister = registerWindowCloseGuard(async () => {
      const session = serializeWorkspaceState(activeProject.workspaceId, activeProject.repoRoot, state);
      await saveSession(session);
    });
    return unregister;
  }, [activeProject.repoRoot, activeProject.workspaceId, state]);

  useEffect(() => {
    if (state.worktrees.length === 0 || state.layout.tabs.length === 0) return;
    const timer = setTimeout(() => {
      const session = serializeWorkspaceState(activeProject.workspaceId, activeProject.repoRoot, state);
      void Promise.resolve(saveSession(session)).catch((error) => console.error("Failed to auto-save session:", error));
    }, 500);
    return () => clearTimeout(timer);
  }, [activeProject.repoRoot, activeProject.workspaceId, state]);

  const [isAddProjectOpen, setIsAddProjectOpen] = useState(false);
  const [createTargetProject, setCreateTargetProject] = useState<RegisteredProject | null>(null);
  const [isCreateOpen, setIsCreateOpen] = useState(false);
  const [isCommandPaletteOpen, setIsCommandPaletteOpen] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [searchLeafId, setSearchLeafId] = useState<string | null>(null);
  const [isSidebarOpen, setIsSidebarOpen] = useState(loadSidebarOpen);
  const [deleteTarget, setDeleteTarget] = useState<Worktree | null>(null);
  const [worktreeStatuses, setWorktreeStatuses] = useState<Record<string, DirtyState | undefined>>({});
  const [pendingWorktreePath, setPendingWorktreePath] = useState<string | null>(null);

  const toggleSidebar = useCallback(() => {
    setIsSidebarOpen((current) => {
      const next = !current;
      persistSidebarOpen(next);
      return next;
    });
  }, []);

  const activeWorktree = useMemo(
    () => state.worktrees.find((worktree) => worktree.path === state.activeWorktreePath) ?? null,
    [state.activeWorktreePath, state.worktrees],
  );

  const handleSelectProject = useCallback(
    (project: RegisteredProject) => {
      if (project.workspaceId === activeProject.workspaceId) return;
      setActiveProjectId(project.workspaceId);
      persistActiveProjectId(project.workspaceId);
      setWorktreeStatuses({});
      setDeleteTarget(null);
      setPendingWorktreePath(null);
    },
    [activeProject.workspaceId],
  );

  const handleRegisteredProject = useCallback((project: RegisteredProject) => {
    setProjects((current) => {
      const next = [...current.filter((candidate) => candidate.workspaceId !== project.workspaceId), project];
      persistProjects(next);
      return next;
    });
    setActiveProjectId(project.workspaceId);
    persistActiveProjectId(project.workspaceId);
    setWorktreeStatuses({});
  }, []);

  const handleSelectWorktree = useCallback(
    (worktree: Worktree) => {
      const ownerId = worktreeIdentity(worktree)?.wsId;
      const owner = ownerId ? projects.find((project) => project.workspaceId === ownerId) : undefined;
      if (owner && owner.workspaceId !== activeProject.workspaceId) {
        handleSelectProject(owner);
        setPendingWorktreePath(worktree.path);
        return;
      }
      void ensureTabForWorktree(worktree).catch(reportRuntimeError);
    },
    [activeProject.workspaceId, ensureTabForWorktree, handleSelectProject, projects, reportRuntimeError],
  );

  useEffect(() => {
    if (!pendingWorktreePath) return;
    const target = state.worktrees.find((worktree) => worktree.path === pendingWorktreePath);
    if (!target) return;
    setPendingWorktreePath(null);
    void ensureTabForWorktree(target).catch(reportRuntimeError);
  }, [ensureTabForWorktree, pendingWorktreePath, reportRuntimeError, state.worktrees]);

  const handleSelectTerminalTab = useCallback(
